const envelope = $('When Called by Another Workflow').first().json;
const policy   = $('Load Retry Policy').first().json;
const proc     = $input.first().json ?? {};

const attempt        = Number(envelope.attempt_count ?? 1);
const ladder         = Array.isArray(policy.ladder_seconds) ? policy.ladder_seconds : [5, 30, 120, 900];
const maxAttempts    = Number(policy.max_attempts ?? 5);
const jitterRatio    = Number(policy.jitter_ratio ?? 0.20);

// The DLQ INSERT is built here as literal SQL instead of via the Postgres node's
// queryReplacement: that field is a comma-joined expression list, so any value or
// expression containing a comma (or a failing sub-expression) silently shifts the
// parameter positions -> "there is no parameter $N" and the poison message can never
// leave the queue. It blocked 4 Berlare orders on 2026-08-06. Literal SQL has no
// positional coupling at all.
function sqlLit(v) {
  if (v === null || v === undefined || v === '') return 'NULL';
  return "'" + String(v).replace(/'/g, "''") + "'";
}
function sqlNum(v) {
  const n = Number(v);
  return Number.isFinite(n) ? String(n) : 'NULL';
}
function buildDlqSql(queueName, msgId, p) {
  const errJson = JSON.stringify({
    message: p?.last_error?.message ?? 'max retries exceeded',
    kind: p?.last_error?.kind ?? null,
    stage: 'retry_ladder',
    http_status: p?.last_error?.http_status ?? null,
    classification: p?.last_error?.classification ?? null,
  });
  return 'WITH archived AS (SELECT public.pgmq_archive_order(' + sqlLit(queueName) + '::text, ' + sqlNum(msgId) + '::bigint) AS ok) '
    + 'INSERT INTO public.dlq_alerts (queue_name, msg_id, canonical_order_id, external_ref, source, location_key, last_error, attempt_count, raw_payload_id) '
    + 'SELECT ' + sqlLit(queueName) + ', ' + sqlNum(msgId) + ', '
    + sqlLit(p?.canonical_order_id) + '::uuid, '
    + sqlLit(p?.external_ref) + ', '
    + sqlLit(p?.source) + '::public.order_source, '
    + sqlLit(p?.location_key) + ', '
    + sqlLit(errJson) + '::jsonb, '
    + sqlNum(p?.attempt_count ?? 0) + ', '
    + sqlNum(p?.raw_payload_id) + '::bigint '
    + 'FROM archived ON CONFLICT (queue_name, msg_id) DO NOTHING RETURNING id';
}

// SAFETY NET: kalau attempt_count > 2x maxAttempts, force archive (mencegah runaway loop seperti k6 incident 1 Mei 2026)
if (Number(envelope.attempt_count ?? 0) > 2 * maxAttempts) {
  const p = { canonical_order_id: envelope.payload?.canonical_order_id ?? null, external_ref: envelope.payload?.external_ref ?? null, source: envelope.payload?.source ?? null, location_key: envelope.payload?.location_key ?? null, raw_payload_id: envelope.raw_payload_id ?? null, attempt_count: attempt, last_error: { message: 'force_archived: attempt_count exceeded 2x max_attempts', kind: 'runaway' } };
  return [{ json: { outcome: 'archived_to_dlq', queue_name: envelope.queue_name, msg_id: envelope.msg_id, attempt_count: attempt, next_vt_seconds: null, classification: { retryable: false, reason: 'force_archived_runaway' }, dlq_payload: p, dlq_sql: buildDlqSql(envelope.queue_name, envelope.msg_id, p), correlation_id: envelope.correlation_id } }];
}

const failed = proc.ok === false || proc.error !== undefined;
let errorCtx = null;
if (failed) {
  if (proc.error) {
    errorCtx = { http_status: proc.error.status ?? proc.error.httpCode ?? proc.error.http_status ?? null, headers: proc.error.headers ?? {}, kind: proc.error.code === 'ETIMEDOUT' ? 'timeout' : (proc.error.kind ?? 'network'), message: proc.error.message ?? 'unknown' };
  } else {
    errorCtx = { http_status: proc.http_status ?? null, headers: proc.headers ?? {}, kind: proc.kind ?? null, message: proc.message ?? 'processor returned ok:false' };
  }
}

function classify(ctx) {
  if (!ctx) return null;
  if (ctx.kind === 'timeout') return { retryable: true,  reason: 'timeout' };
  if (ctx.kind === 'network') return { retryable: true,  reason: 'network' };
  const s = ctx.http_status;
  if (s == null)             return { retryable: true,  reason: 'network' };
  if (s >= 500 && s <= 599)  return { retryable: true,  reason: 'server_error' };
  if (s === 429) {
    const ra = ctx.headers ? (ctx.headers['retry-after'] ?? ctx.headers['Retry-After']) : null;
    let retry_after_ms = null;
    if (ra != null && ra !== '') {
      const n = Number(ra);
      if (Number.isFinite(n)) retry_after_ms = Math.max(0, n * 1000);
      else { const t = Date.parse(ra); if (Number.isFinite(t)) retry_after_ms = Math.max(0, t - Date.now()); }
    }
    return { retryable: true, reason: 'rate_limited', retry_after_ms };
  }
  if (s === 401)             return { retryable: true,  reason: 'auth', refresh_token_first: true };
  if (s === 400)             return { retryable: false, reason: 'bad_payload' };
  if (s === 403)             return { retryable: false, reason: 'forbidden' };
  if (s === 409)             return { retryable: false, reason: 'duplicate' };
  return { retryable: false, reason: 'unknown' };
}

function nextVisibilityTimeout(att, lad, jr) {
  const idx = Math.min(Math.max(att, 1), lad.length) - 1;
  const base = lad[idx];
  const jitter = (Math.random() * 2 - 1) * jr;
  return Math.max(1, Math.round(base * (1 + jitter)));
}

let outcome, next_vt_seconds = null, dlq_payload = null, classification = null;

if (!failed) {
  outcome = 'success';
} else {
  classification = classify(errorCtx);
  const exhausted = attempt >= maxAttempts;
  if (!classification.retryable || exhausted) {
    outcome = 'archived_to_dlq';
    dlq_payload = { canonical_order_id: envelope.payload?.canonical_order_id ?? null, external_ref: envelope.payload?.external_ref ?? null, source: envelope.payload?.source ?? null, location_key: envelope.payload?.location_key ?? null, raw_payload_id: envelope.raw_payload_id ?? null, attempt_count: attempt, last_error: { ...errorCtx, classification } };
  } else {
    outcome = 'retry_scheduled';
    if (classification.reason === 'rate_limited' && classification.retry_after_ms != null) {
      next_vt_seconds = Math.max(1, Math.ceil(classification.retry_after_ms / 1000));
    } else {
      next_vt_seconds = nextVisibilityTimeout(attempt, ladder, jitterRatio);
    }
  }
}

return [{ json: { outcome, queue_name: envelope.queue_name, msg_id: envelope.msg_id, attempt_count: attempt + (outcome === 'retry_scheduled' ? 1 : 0), next_vt_seconds, classification, dlq_payload, dlq_sql: dlq_payload ? buildDlqSql(envelope.queue_name, envelope.msg_id, dlq_payload) : null, correlation_id: envelope.correlation_id } }];

// Pass the envelope's payload as the sub-workflow input. n8n executeWorkflow
// otherwise forwards the most recent item ($json from Load Retry Policy), so
// the processor would never see raw_id / external_ref etc.
return [{ json: $('When Called by Another Workflow').first().json.payload }];
